    /* =========================================================================
       5. RENDERIZADO DE TARJETAS LIMPIAS (SIN SATURACIÓN VISUAL)
    ========================================================================= */
    function renderizarTarjeta(prod) {
      const esPremium = prod.linea === "PREMIUM";
      const esBasic = prod.linea === "BASIC";
      const esCombo = prod.tipo === "COMBO";

      let etiquetaBadge = "";
      if (esBasic) {
        etiquetaBadge = `<span class="sky-pill px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider uppercase">BASIC</span>`;
      } else if (esPremium) {
        etiquetaBadge = `<span class="silver-pill px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider uppercase">PREMIUM</span>`;
      } else if (esCombo) {
        etiquetaBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider uppercase bg-[#CFE7FF] text-sky-950 border border-[#7CC0FF]">COMBO / KIT</span>`;
      } else {
        etiquetaBadge = `<span class="px-2.5 py-0.5 rounded-full text-[10px] font-bold tracking-wider uppercase bg-[#E6F3FF] text-sky-800 border border-[#A8D8F8]">ACCESSORY</span>`;
      }

      return `
        <article class="group rounded-[26px] ${esPremium ? 'premium-card shadow-premium' : 'bg-white border border-sky-100 shadow-card'} p-4 sm:p-5 flex flex-col justify-between hover:shadow-soft hover:-translate-y-1 transition-all duration-300">
          <div>
            <!-- Cabecera minimalista: Número + Colección + Botón Vista Rápida -->
            <div class="flex items-center justify-between gap-2 mb-3">
              <div class="flex items-center gap-1.5">
                <span class="text-xs font-bold px-2.5 py-0.5 rounded-lg ${esPremium ? 'bg-slate-200/70 text-slate-800' : 'bg-[#E6F3FF] text-sky-900'}">
                  ${prod.numero}
                </span>
                ${etiquetaBadge}
              </div>

              <button type="button" onclick="abrirDetalleProducto('${prod.uid}')" title="Ver detalles"
                class="w-7 h-7 rounded-full bg-slate-50 hover:bg-[#E6F3FF] text-slate-500 hover:text-sky-800 flex items-center justify-center text-xs transition-colors">
                ⓘ
              </button>
            </div>

            <!-- Imagen / Ilustración del producto (clic abre vista rápida) -->
            <div class="cursor-pointer" onclick="abrirDetalleProducto('${prod.uid}')">
              ${crearIlustracionCatalogo(prod)}
            </div>

            <!-- Disponibilidad y Nombre -->
            <div class="mt-3.5 flex items-center gap-1.5">
              <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>
              <span class="text-[11px] font-semibold text-emerald-700">Disponible</span>
            </div>

            <h3 onclick="abrirDetalleProducto('${prod.uid}')"
              class="cursor-pointer font-bold text-base text-slate-900 mt-1 leading-snug group-hover:text-[#52A8F8] transition-colors">
              ${prod.nombre}
            </h3>

            <!-- Descripción concisa (2 líneas máx para no saturar la tarjeta) -->
            <p class="text-xs text-slate-600 mt-1.5 leading-relaxed line-clamp-2">
              ${prod.descripcion}
            </p>
          </div>

          <!-- Precio en COP y Botón Agregar al carrito -->
          <div class="mt-5 pt-3.5 border-t ${esPremium ? 'border-slate-200' : 'border-sky-50'} flex items-center justify-between gap-2">
            <span class="text-base font-bold text-slate-900">${formatearCOP(prod.precio)}</span>

            <button type="button" onclick="agregarAlCarrito('${prod.uid}')"
              class="inline-flex items-center gap-1.5 px-4 py-2.5 rounded-full ${esPremium ? 'bg-slate-900 hover:bg-slate-800' : 'bg-[#52A8F8] hover:bg-sky-600'} text-white text-xs font-semibold shadow-xs active:scale-95 transition-all">
              <span>Agregar</span>
            </button>
          </div>
        </article>
      `;
    }

    function renderizarSkincare() {
      const grid = document.getElementById("grid-skincare");
      const vacio = document.getElementById("vacio-skincare");
      const contador = document.getElementById("contador-skincare");
      const q = filtrosSkincare.busqueda.trim().toLowerCase();

      const lista = PRODUCTOS_SKINCARE
        .filter((p) => {
          const okLinea = filtrosSkincare.linea === "TODOS" || p.linea === filtrosSkincare.linea;
          const okPrecio = p.precio <= filtrosSkincare.precioMax;
          const okTexto = !q || p.nombre.toLowerCase().includes(q) || p.descripcion.toLowerCase().includes(q) || p.numero.includes(q);
          return okLinea && okPrecio && okTexto;
        })
        .sort((a, b) => Number(a.numero) - Number(b.numero));

      contador.textContent = `Mostrando ${lista.length} de 20 productos`;

      if (lista.length === 0) {
        grid.innerHTML = "";
        vacio.classList.remove("hidden");
        return;
      }
      vacio.classList.add("hidden");
      grid.innerHTML = lista.map(renderizarTarjeta).join("");
    }

    function renderizarAccesorios() {
      const grid = document.getElementById("grid-accesorios");
      const vacio = document.getElementById("vacio-accesorios");
      const contador = document.getElementById("contador-accesorios");
      const q = filtrosAccesorios.busqueda.trim().toLowerCase();

      const lista = PRODUCTOS_ACCESORIOS
        .filter((p) => {
          const okTipo = filtrosAccesorios.tipo === "TODOS" || p.tipo === filtrosAccesorios.tipo;
          const okPrecio = p.precio <= filtrosAccesorios.precioMax;
          const okTexto = !q || p.nombre.toLowerCase().includes(q) || p.descripcion.toLowerCase().includes(q) || p.numero.includes(q);
          return okTipo && okPrecio && okTexto;
        })
        .sort((a, b) => Number(a.numero) - Number(b.numero));

      contador.textContent = `Mostrando ${lista.length} de 20 productos`;

      if (lista.length === 0) {
        grid.innerHTML = "";
        vacio.classList.remove("hidden");
        return;
      }
      vacio.classList.add("hidden");
      grid.innerHTML = lista.map(renderizarTarjeta).join("");
    }

    function irASkincareConFiltro(linea) {
      filtrosSkincare.linea = linea;
      document.querySelectorAll(".btn-sk-linea").forEach((btn) => {
        const activo = btn.dataset.skLinea === linea;
        btn.classList.toggle("ring-2", activo);
        btn.classList.toggle("ring-[#52A8F8]", activo);
      });
      renderizarSkincare();
      document.getElementById("apartado-skincare").scrollIntoView({ behavior: "smooth" });
    }

    function reiniciarSkincare() {
      filtrosSkincare = { linea: "TODOS", busqueda: "", precioMax: 90000 };
      document.getElementById("sk-buscador").value = "";
      document.getElementById("sk-precio").value = 90000;
      document.getElementById("sk-precio-valor").textContent = "$90.000 COP";
      renderizarSkincare();
    }

    function reiniciarAccesorios() {
      filtrosAccesorios = { tipo: "TODOS", busqueda: "", precioMax: 70000 };
      document.getElementById("ac-buscador").value = "";
      document.getElementById("ac-precio").value = 70000;
      document.getElementById("ac-precio-valor").textContent = "$70.000 COP";
      renderizarAccesorios();
    }

    /* =========================================================================
       6. MODAL DE VISTA RÁPIDA DE PRODUCTO
    ========================================================================= */
    function abrirDetalleProducto(uid) {
      const prod = TODOS_LOS_PRODUCTOS.find((p) => p.uid === uid);
      if (!prod) return;

      const esPremium = prod.linea === "PREMIUM";
      const subEtiqueta = prod.categoria === "skincare"
        ? `SKINCARE • Colección ${prod.linea}`
        : `SKINCARY ACCESSORIES • ${prod.tipo === "COMBO" ? "Combo & Kit" : "Accesorio Individual"}`;

      document.getElementById("contenido-modal-detalle").innerHTML = `
        <div class="space-y-4">
          <div class="flex items-center gap-2">
            <span class="px-2.5 py-1 rounded-full text-xs font-bold ${esPremium ? 'silver-pill' : 'sky-pill'}">#${prod.numero}</span>
            <span class="text-xs font-semibold text-slate-500">${subEtiqueta}</span>
          </div>

          ${crearIlustracionCatalogo(prod)}

          <div>
            <h3 class="font-editorial text-2xl sm:text-3xl font-bold text-slate-900">${prod.nombre}</h3>
            <p class="text-sm text-slate-600 mt-2 leading-relaxed">${prod.descripcion}</p>
          </div>

          <div class="pt-4 border-t border-sky-100 flex items-center justify-between gap-4">
            <div>
              <span class="text-[11px] uppercase tracking-wider text-slate-400 block">Precio oficial</span>
              <span class="text-xl font-bold text-slate-900">${formatearCOP(prod.precio)}</span>
            </div>

            <button type="button" onclick="agregarAlCarrito('${prod.uid}'); cerrarDetalleProducto();"
              class="px-6 py-3 rounded-full bg-slate-900 hover:bg-[#52A8F8] text-white text-sm font-semibold shadow-soft transition-all">
              Agregar al carrito
            </button>
          </div>
        </div>
      `;

      const modal = document.getElementById("modal-detalle-producto");
      modal.classList.remove("hidden");
      modal.classList.add("flex");
    }

    function cerrarDetalleProducto() {
      const modal = document.getElementById("modal-detalle-producto");
      modal.classList.add("hidden");
      modal.classList.remove("flex");
    }

    /* =========================================================================
       7. CARRITO DE COMPRAS Y CHECKOUT WHATSAPP
    ========================================================================= */
    function guardarCarritoLocal() {
      try {
        localStorage.setItem("skincary_cart_2026", JSON.stringify(carrito));
      } catch (e) {}
    }

    function agregarAlCarrito(uid) {
      const prod = TODOS_LOS_PRODUCTOS.find((p) => p.uid === uid);
      if (!prod) return;

      const itemExistente = carrito.find((i) => i.uid === uid);
      if (itemExistente) {
        itemExistente.cantidad += 1;
      } else {
        carrito.push({
          uid: prod.uid,
          numero: prod.numero,
          nombre: prod.nombre,
          etiqueta: prod.linea || prod.tipo,
          precio: prod.precio,
          cantidad: 1
        });
      }

      guardarCarritoLocal();
      actualizarCarritoUI();
      mostrarToast(`Agregado: ${prod.nombre}`);
    }

    function modificarCantidad(uid, delta) {
      const idx = carrito.findIndex((i) => i.uid === uid);
      if (idx === -1) return;

      carrito[idx].cantidad += delta;
      if (carrito[idx].cantidad <= 0) carrito.splice(idx, 1);

      guardarCarritoLocal();
      actualizarCarritoUI();
    }

    function quitarDelCarrito(uid) {
      carrito = carrito.filter((i) => i.uid !== uid);
      guardarCarritoLocal();
      actualizarCarritoUI();
      mostrarToast("Producto eliminado del carrito");
    }

    function totalEnPesos() {
      return carrito.reduce((sum, item) => sum + item.precio * item.cantidad, 0);
    }

    function totalUnidades() {
      return carrito.reduce((sum, item) => sum + item.cantidad, 0);
    }

    function actualizarCarritoUI() {
      const unidades = totalUnidades();
      const total = totalEnPesos();

      document.getElementById("contador-carrito").textContent = unidades;
      document.getElementById("drawer-contador").textContent = unidades;
      document.getElementById("subtotal-carrito").textContent = formatearCOP(total);
      document.getElementById("total-carrito").textContent = formatearCOP(total);

      const listaEl = document.getElementById("lista-items-carrito");
      const vacioEl = document.getElementById("carrito-vacio-estado");
      const footerEl = document.getElementById("footer-carrito");

      if (carrito.length === 0) {
        listaEl.innerHTML = "";
        vacioEl.classList.remove("hidden");
        footerEl.classList.add("hidden");
        cambiarVistaCarrito("items");
        return;
      }

      vacioEl.classList.add("hidden");
      footerEl.classList.remove("hidden");

      listaEl.innerHTML = carrito.map((item) => `
        <div class="p-3.5 rounded-2xl bg-[#E6F3FF]/45 border border-[#CFE7FF] flex items-center justify-between gap-3">
          <div class="min-w-0 flex-1">
            <div class="flex items-center gap-1.5">
              <span class="text-[10px] font-bold px-2 py-0.5 rounded bg-white text-sky-900 border border-sky-100">#${item.numero}</span>
              <span class="text-[10px] font-semibold uppercase text-slate-500">${item.etiqueta}</span>
            </div>
            <h4 class="font-bold text-sm text-slate-900 truncate mt-1">${item.nombre}</h4>
            <p class="text-xs font-semibold text-sky-900 mt-0.5">${formatearCOP(item.precio)} c/u</p>
          </div>

          <div class="flex items-center gap-2">
            <div class="inline-flex items-center bg-white rounded-full border border-[#7CC0FF]/60 p-0.5">
              <button type="button" onclick="modificarCantidad('${item.uid}', -1)" aria-label="Disminuir"
                class="w-7 h-7 rounded-full hover:bg-[#E6F3FF] text-slate-800 font-bold text-sm">−</button>
              <span class="w-7 text-center text-xs font-bold text-slate-900">${item.cantidad}</span>
              <button type="button" onclick="modificarCantidad('${item.uid}', 1)" aria-label="Aumentar"
                class="w-7 h-7 rounded-full hover:bg-[#E6F3FF] text-slate-800 font-bold text-sm">+</button>
            </div>

            <button type="button" onclick="quitarDelCarrito('${item.uid}')" aria-label="Eliminar"
              class="p-2 rounded-full text-slate-400 hover:text-rose-600 hover:bg-rose-50 transition-colors">
              <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"/></svg>
            </button>
          </div>
        </div>
      `).join("");

      // Actualizar resumen del pedido
      document.getElementById("resumen-pedido-lista").innerHTML = carrito.map((item) => `
        <div class="flex items-center justify-between gap-2">
          <span class="truncate">${item.cantidad}x ${item.nombre}</span>
          <span class="font-semibold whitespace-nowrap">${formatearCOP(item.precio * item.cantidad)}</span>
        </div>
      `).join("");
      document.getElementById("resumen-pedido-total").textContent = formatearCOP(total);
    }

    function abrirCarrito() {
      document.getElementById("overlay-carrito").classList.remove("hidden");
      document.body.style.overflow = "hidden";
    }

    function cerrarCarrito() {
      document.getElementById("overlay-carrito").classList.add("hidden");
      document.body.style.overflow = "";
    }

    function cambiarVistaCarrito(vista) {
      const vItems = document.getElementById("vista-carrito-items");
      const vCheckout = document.getElementById("vista-carrito-checkout");
      const fCarrito = document.getElementById("footer-carrito");

      if (vista === "checkout" && carrito.length > 0) {
        vItems.classList.add("hidden");
        fCarrito.classList.add("hidden");
        vCheckout.classList.remove("hidden");
      } else {
        vCheckout.classList.add("hidden");
        vItems.classList.remove("hidden");
        if (carrito.length > 0) fCarrito.classList.remove("hidden");
      }
    }

    function procesarEnvioWhatsApp(e) {
      e.preventDefault();
      if (carrito.length === 0) return;

      const nombre = document.getElementById("inp-nombre").value.trim();
      const telefono = document.getElementById("inp-telefono").value.trim();
      const ciudad = document.getElementById("inp-ciudad").value.trim();
      const direccion = document.getElementById("inp-direccion").value.trim();
      const entrega = document.getElementById("inp-entrega").value;
      const obs = document.getElementById("inp-observaciones").value.trim();

      const detalleProductos = carrito.map((i) =>
        `• [${i.numero}] ${i.nombre} (${i.etiqueta}) x${i.cantidad} — ${formatearCOP(i.precio * i.cantidad)}`
      ).join("\n");

      const mensaje = [
        "☁️ *PEDIDO ONLINE — SKINCARY* ☁️",
        "",
        "*Detalle de productos:*",
        detalleProductos,
        "",
        `💰 *Total del pedido:* ${formatearCOP(totalEnPesos())}`,
        "",
        "*Datos del comprador:*",
        `• Nombre: ${nombre}`,
        `• Teléfono/WhatsApp: ${telefono}`,
        `• Ciudad: ${ciudad}`,
        `• Dirección: ${direccion}`,
        `• Método de entrega: ${entrega}`,
        obs ? `• Observaciones: ${obs}` : null,
        "",
        "*Medios de pago oficiales:* Nequi 3122297580 | Bancolombia @perea340",
        "✨ _Tu momento de cuidado, tu momento SKINCARY_"
      ].filter(Boolean).join("\n");

      const numeroLimpio = WHATSAPP_TIENDA.replace(/\D/g, "");
      if (!numeroLimpio) {
        mostrarToast("Configura WHATSAPP_TIENDA en el código; abriendo WhatsApp...");
        window.open(`https://wa.me/?text=${encodeURIComponent(mensaje)}`, "_blank", "noopener,noreferrer");
        return;
      }

      window.open(`https://wa.me/${numeroLimpio}?text=${encodeURIComponent(mensaje)}`, "_blank", "noopener,noreferrer");
      mostrarToast("Redirigiendo a WhatsApp con tu pedido...");
    }

    function abrirWhatsAppContacto() {
      const numeroLimpio = WHATSAPP_TIENDA.replace(/\D/g, "");
      const saludo = "Hola SKINCARY ☁️✨ Me gustaría recibir información sobre sus productos de Skincare y Accesorios.";
      if (!numeroLimpio) {
        mostrarToast("Configura WHATSAPP_TIENDA en el código; abriendo WhatsApp...");
        window.open(`https://wa.me/?text=${encodeURIComponent(saludo)}`, "_blank", "noopener,noreferrer");
        return;
      }
      window.open(`https://wa.me/${numeroLimpio}?text=${encodeURIComponent(saludo)}`, "_blank", "noopener,noreferrer");
    }

    /* =========================================================================
       8. RESEÑAS PERSISTENTES EN LOCALSTORAGE
    ========================================================================= */
    const RESENAS_BASE = [
      {
        nombre: "Camila Rodríguez • Cartagena",
        producto: "Escudo Diario SPF 50 (BASIC)",
        estrellas: 5,
        comentario: "Me encantó la textura ligera del protector solar y el envase blanco con azul cielo es precioso. No deja sensación pesada."
      },
      {
        nombre: "Sofía Martínez • Medellín",
        producto: "CinnaBright Radiance Pro (PREMIUM)",
        estrellas: 5,
        comentario: "Los detalles plateados de la línea PREMIUM se ven súper delicados y elegantes. El sérum deja la piel luminosa y suave."
      },
      {
        nombre: "Mariana López • Bogotá",
        producto: "CinnaSkin Spa Day Set (Accessories)",
        estrellas: 5,
        comentario: "La banda y las muñequeras son súper suaves y prácticas para lavarme la cara sin mojarme. Llegó rápido por envío nacional."
      }
    ];

    function cargarYRenderizarResenas() {
      let guardadas = [];
      try {
        const raw = localStorage.getItem("skincary_resenas_2026");
        if (raw) guardadas = JSON.parse(raw);
      } catch (e) { guardadas = []; }

      const todas = [...guardadas, ...RESENAS_BASE];
      const grid = document.getElementById("grid-resenas");
      grid.innerHTML = todas.map((r) => {
        const stars = "★".repeat(r.estrellas) + "☆".repeat(5 - r.estrellas);
        return `
          <article class="bg-white rounded-[24px] p-6 border border-sky-100 shadow-card flex flex-col justify-between">
            <div>
              <div class="flex items-center justify-between mb-3">
                <span class="text-amber-400 text-sm tracking-widest">${stars}</span>
                <span class="text-[10px] font-bold uppercase tracking-wider px-2.5 py-0.5 rounded-full bg-[#E6F3FF] text-sky-900">Verificada</span>
              </div>
              <p class="text-sm text-slate-700 leading-relaxed">“${r.comentario}”</p>
            </div>
            <div class="mt-4 pt-3 border-t border-slate-100 text-xs">
              <span class="font-bold text-slate-900 block">${r.nombre}</span>
              <span class="text-[#52A8F8] font-medium">${r.producto}</span>
            </div>
          </article>
        `;
      }).join("");
    }

    /* =========================================================================
       9. UTILIDADES UI (COPIAR PORTAPAPELES Y TOAST)
    ========================================================================= */
    let toastTimer = null;
    function mostrarToast(msg) {
      const el = document.getElementById("toast-skincary");
      document.getElementById("toast-texto").textContent = msg;
      el.classList.remove("opacity-0", "translate-y-3");
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => el.classList.add("opacity-0", "translate-y-3"), 2600);
    }

    function copiarAlPortapapeles(texto, aviso) {
      const aux = document.createElement("input");
      aux.value = texto;
      document.body.appendChild(aux);
      aux.select();
      document.execCommand("copy");
      document.body.removeChild(aux);
      mostrarToast(`${aviso}: ${texto}`);
    }

    /* =========================================================================
       9.5 CONTROL DE MODO EDICIÓN MULTIMEDIA (ESPACIOS PARA FOTOS Y VIDEO)
    ========================================================================= */
    function toggleModoEdicion() {
      modoEdicionActivo = !modoEdicionActivo;
      const panel = document.getElementById("panel-estructura-archivos");
      const slotHero = document.getElementById("slot-video-hero");
      const btnEdicion = document.getElementById("btn-toggle-edicion");
      const textoBtn = document.getElementById("texto-btn-edicion");

      if (modoEdicionActivo) {
        panel.classList.remove("hidden");
        slotHero.classList.remove("hidden");
        btnEdicion.classList.add("bg-slate-900", "text-white");
        btnEdicion.classList.remove("bg-[#E6F3FF]", "text-sky-900");
        textoBtn.textContent = "Cerrar Edición";
        mostrarToast("Modo Fotos/Video activo: haz clic en cualquier espacio para probar tus archivos");
      } else {
        panel.classList.add("hidden");
        slotHero.classList.add("hidden");
        btnEdicion.classList.remove("bg-slate-900", "text-white");
        btnEdicion.classList.add("bg-[#E6F3FF]", "text-sky-900");
        textoBtn.textContent = "Modo Fotos/Video";
      }

      renderizarSkincare();
      renderizarAccesorios();
    }

    function cargarFotoLocalProducto(event, uid) {
      const archivo = event.target.files && event.target.files[0];
      if (!archivo) return;

      const prod = TODOS_LOS_PRODUCTOS.find((p) => p.uid === uid);
      const urlTemporal = URL.createObjectURL(archivo);
      fotosPrevisualizadas[uid] = urlTemporal;

      renderizarSkincare();
      renderizarAccesorios();
      if (prod) {
        mostrarToast(`Vista previa lista. Guárdala como: ${prod.imagenReal}`);
      }
    }

    /* =========================================================================
       10. INICIALIZACIÓN DE EVENTOS
    ========================================================================= */
    document.addEventListener("DOMContentLoaded", () => {
      renderizarSkincare();
      renderizarAccesorios();
      actualizarCarritoUI();
      cargarYRenderizarResenas();

      // Botón Modo Edición Multimedia y carga de Video de Portada
      document.getElementById("btn-toggle-edicion").addEventListener("click", toggleModoEdicion);

      document.getElementById("input-video-hero").addEventListener("change", (e) => {
        const archivo = e.target.files && e.target.files[0];
        if (!archivo) return;
        const videoEl = document.getElementById("hero-video");
        videoEl.src = URL.createObjectURL(archivo);
        videoEl.play().catch(() => {});
        mostrarToast("Video cargado en portada. Guárdalo en: assets/video/109166.mp4");
      });

      // Filtros Skincare (BASIC / PREMIUM / TODOS)
      document.querySelectorAll(".btn-sk-linea").forEach((btn) => {
        btn.addEventListener("click", () => {
          filtrosSkincare.linea = btn.dataset.skLinea;
          document.querySelectorAll(".btn-sk-linea").forEach((b) => {
            const on = b === btn;
            b.classList.toggle("ring-2", on);
            b.classList.toggle("ring-[#52A8F8]", on);
          });
          renderizarSkincare();
        });
      });

      document.getElementById("sk-buscador").addEventListener("input", (e) => {
        filtrosSkincare.busqueda = e.target.value;
        renderizarSkincare();
      });

      document.getElementById("sk-precio").addEventListener("input", (e) => {
        filtrosSkincare.precioMax = Number(e.target.value);
        document.getElementById("sk-precio-valor").textContent = formatearCOP(filtrosSkincare.precioMax);
        renderizarSkincare();
      });

      // Filtros Accesorios
      document.querySelectorAll(".btn-ac-tipo").forEach((btn) => {
        btn.addEventListener("click", () => {
          filtrosAccesorios.tipo = btn.dataset.acTipo;
          document.querySelectorAll(".btn-ac-tipo").forEach((b) => {
            const on = b === btn;
            b.classList.toggle("ring-2", on);
            b.classList.toggle("ring-[#52A8F8]", on);
          });
          renderizarAccesorios();
        });
      });

      document.getElementById("ac-buscador").addEventListener("input", (e) => {
        filtrosAccesorios.busqueda = e.target.value;
        renderizarAccesorios();
      });

      document.getElementById("ac-precio").addEventListener("input", (e) => {
        filtrosAccesorios.precioMax = Number(e.target.value);
        document.getElementById("ac-precio-valor").textContent = formatearCOP(filtrosAccesorios.precioMax);
        renderizarAccesorios();
      });

      // Buscador global de la barra superior (filtra ambos apartados y desplaza suavemente)
      const sincronizarBuscadorGlobal = (valor) => {
        filtrosSkincare.busqueda = valor;
        filtrosAccesorios.busqueda = valor;
        document.getElementById("sk-buscador").value = valor;
        document.getElementById("ac-buscador").value = valor;
        renderizarSkincare();
        renderizarAccesorios();
      };

      document.getElementById("input-buscador-global").addEventListener("input", (e) => {
        sincronizarBuscadorGlobal(e.target.value);
      });
      document.getElementById("input-buscador-movil").addEventListener("input", (e) => {
        sincronizarBuscadorGlobal(e.target.value);
      });

      // Controles Carrito y Modal Vista Rápida
      document.getElementById("btn-abrir-carrito").addEventListener("click", abrirCarrito);
      document.getElementById("btn-cerrar-carrito").addEventListener("click", cerrarCarrito);
      document.getElementById("backdrop-carrito").addEventListener("click", cerrarCarrito);

      document.getElementById("btn-cerrar-detalle").addEventListener("click", cerrarDetalleProducto);
      document.getElementById("backdrop-modal-detalle").addEventListener("click", cerrarDetalleProducto);

      document.getElementById("btn-menu-movil").addEventListener("click", () => {
        document.getElementById("menu-movil").classList.toggle("hidden");
      });

      document.getElementById("form-pedido-whatsapp").addEventListener("submit", procesarEnvioWhatsApp);

      // Control Reproducir / Pausar Video de fondo (109166.mp4)
      const videoEl = document.getElementById("hero-video");
      const btnVideo = document.getElementById("btn-toggle-video");
      const iconVideo = document.getElementById("video-icon");
      const labelVideo = document.getElementById("video-label");

      btnVideo.addEventListener("click", () => {
        if (videoEl.paused) {
          videoEl.play().catch(() => {});
          iconVideo.textContent = "❚❚";
          labelVideo.textContent = "Pausar video";
        } else {
          videoEl.pause();
          iconVideo.textContent = "▶";
          labelVideo.textContent = "Reproducir video";
        }
      });

      // Formulario de nueva reseña
      const formRes = document.getElementById("form-nueva-resena");
      document.getElementById("btn-abrir-form-resena").addEventListener("click", () => formRes.classList.toggle("hidden"));
      document.getElementById("btn-cerrar-form-resena").addEventListener("click", () => formRes.classList.add("hidden"));

      formRes.addEventListener("submit", (e) => {
        e.preventDefault();
        const nueva = {
          nombre: document.getElementById("res-nombre").value.trim(),
          producto: document.getElementById("res-producto").value.trim(),
          estrellas: Number(document.getElementById("res-estrellas").value),
          comentario: document.getElementById("res-comentario").value.trim()
        };
        if (!nueva.nombre || !nueva.producto || !nueva.comentario) return;

        let guardadas = [];
        try {
          const raw = localStorage.getItem("skincary_resenas_2026");
          if (raw) guardadas = JSON.parse(raw);
          guardadas.unshift(nueva);
          localStorage.setItem("skincary_resenas_2026", JSON.stringify(guardadas));
        } catch (err) {}

        cargarYRenderizarResenas();
        formRes.reset();
        formRes.classList.add("hidden");
        mostrarToast("¡Tu reseña se publicó correctamente!");
      });
    });

/* JesChat: asistente sencillo con los datos del catálogo */
(function () {
  const EMAIL = "jakejay271@gmail.com";
  const btn = document.getElementById("jeschat-btn");
  const panel = document.getElementById("jeschat-panel");
  const msgs = document.getElementById("jeschat-mensajes");
  const chips = document.getElementById("jeschat-chips");
  const form = document.getElementById("jeschat-form");
  const input = document.getElementById("jeschat-input");
  const norm = (t) => t.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const cop = (n) => "$" + n.toLocaleString("es-CO") + " COP";
  const todos = () => [].concat(PRODUCTOS_SKINCARE, PRODUCTOS_ACCESORIOS);

  function agregar(texto, quien) {
    const d = document.createElement("div");
    d.className = quien === "yo" ? "flex justify-end" : "flex justify-start";
    const b = document.createElement("div");
    b.className = (quien === "yo" ? "bg-[#52A8F8] text-white" : "bg-white border border-[#CFE7FF] text-slate-800") + " px-3.5 py-2 rounded-2xl max-w-[85%] whitespace-pre-line";
    b.textContent = texto;
    d.appendChild(b);
    msgs.appendChild(d);
    msgs.scrollTop = msgs.scrollHeight;
  }

  function listar(arr) {
    return arr.map((p) => "• " + p.nombre + " – " + cop(p.precio)).join("\n");
  }

  function responder(q) {
    const t = norm(q);
    const prod = todos().find((p) => t.includes(norm(p.nombre)));
    if (prod) return prod.nombre + " (" + (prod.linea || prod.tipo) + ")\n" + prod.descripcion + "\nPrecio: " + cop(prod.precio) + ".";
    if (/hola|buenas|hey|buen dia|buenos/.test(t)) return "¡Hola! Soy JesChat ☁️ Puedo ayudarte con productos, precios, pagos y contacto.";
    if (/basic/.test(t)) return "Colección BASIC:\n" + listar(PRODUCTOS_SKINCARE.filter((p) => p.linea === "BASIC"));
    if (/premium/.test(t)) return "Colección PREMIUM:\n" + listar(PRODUCTOS_SKINCARE.filter((p) => p.linea === "PREMIUM"));
    if (/combo|kit|set/.test(t)) return "Combos y kits:\n" + listar(PRODUCTOS_ACCESORIOS.filter((p) => /combo|kit|set|duo|collection|ritual/i.test(p.nombre) || p.tipo !== "INDIVIDUAL"));
    if (/accesorio/.test(t)) return "Tenemos 20 accesorios (15 individuales y 5 combos). Mira la sección Accesorios o pregúntame por uno, por ejemplo: SkinnaRoll Sleep Mask.";
    if (/skincare|facial|crema|serum|tonico|mascarilla|limpiador|solar|protector/.test(t)) return "Skincare tiene 20 productos: 10 BASIC y 10 PREMIUM. Escribe BASIC o PREMIUM para ver la lista, o el nombre de un producto para ver su precio.";
    if (/pago|nequi|bancolombia|pagar/.test(t)) return "Medios de pago: Nequi 3122297580 y Bancolombia @perea340. También puedes pagar contraentrega.";
    if (/envio|entrega|domicilio/.test(t)) return "Al finalizar tu pedido en el carrito eliges la forma de entrega y se envía por WhatsApp para confirmarlo.";
    if (/contacto|correo|email|mail|escribir|whatsapp/.test(t)) return "Escríbenos a " + EMAIL + " o por el botón de WhatsApp al final de la página.";
    if (/gracias/.test(t)) return "¡Con gusto! 💙";
    return "No estoy segura de eso 🙈. Prueba con el nombre de un producto, BASIC, PREMIUM, accesorios, pagos o contacto. También puedes escribir a " + EMAIL + ".";
  }

  function enviar(texto) {
    const q = texto.trim();
    if (!q) return;
    agregar(q, "yo");
    setTimeout(() => agregar(responder(q), "bot"), 250);
  }

  ["BASIC", "PREMIUM", "Accesorios", "Combos", "Pagos", "Contacto"].forEach((c) => {
    const b = document.createElement("button");
    b.type = "button";
    b.textContent = c;
    b.className = "px-3 py-1 rounded-full text-[11px] font-semibold bg-[#E6F3FF] text-sky-900 border border-[#7CC0FF]/50 hover:bg-[#CFE7FF]";
    b.addEventListener("click", () => enviar(c));
    chips.appendChild(b);
  });

  let saludo = false;
  function alternar(abrir) {
    const mostrar = abrir === undefined ? panel.classList.contains("hidden") : abrir;
    panel.classList.toggle("hidden", !mostrar);
    panel.classList.toggle("flex", mostrar);
    if (mostrar && !saludo) {
      saludo = true;
      agregar("¡Hola! Soy JesChat ☁️, el asistente de SKINCARY. ¿En qué te ayudo?", "bot");
    }
    if (mostrar) input.focus();
  }
  btn.addEventListener("click", () => alternar());
  document.getElementById("jeschat-cerrar").addEventListener("click", () => alternar(false));
  form.addEventListener("submit", (e) => { e.preventDefault(); enviar(input.value); input.value = ""; });
})();